//! bluetooth.library's functions: the Bluetooth controllers, brought up
//! and run by the library's task, and who is told when they change. Open
//! it with OpenLibrary("bluetooth.library", 1); the structures are in
//! sdk.bluetooth.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/bluetooth_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const exec = @import("../libs/exec/exec.zig");
const bluetooth = @import("../libs/bluetooth/bluetooth.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "bluetooth.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const AddBTController = libraries.lvo(4);
    pub const RemBTController = libraries.lvo(5);
    pub const ObtainBTControllers = libraries.lvo(6);
    pub const ReleaseBTControllers = libraries.lvo(7);
    pub const AddBTNotify = libraries.lvo(8);
    pub const RemBTNotify = libraries.lvo(9);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const AddBTController = *const fn (*BluetoothBase, [*:0]const u8, u32) callconv(.c) i32;
    pub const RemBTController = *const fn (*BluetoothBase, [*:0]const u8, u32) callconv(.c) void;
    pub const ObtainBTControllers = *const fn (*BluetoothBase) callconv(.c) ?*exec.List;
    pub const ReleaseBTControllers = *const fn (*BluetoothBase, ?*exec.List) callconv(.c) void;
    pub const AddBTNotify = *const fn (*BluetoothBase, *exec.Task, u32) callconv(.c) ?*bluetooth.BTNotify;
    pub const RemBTNotify = *const fn (*BluetoothBase, ?*bluetooth.BTNotify) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const BluetoothBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *BluetoothBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A controller offered by its driver: the device's unit opened by the library's task, which brings it up. The controller's number, or BTERR_*.
    pub fn AddBTController(self: *BluetoothBase, device_name: [*:0]const u8, unit: u32) i32 {
        return libraries.call(self, LVO.AddBTController, Fn.AddBTController, .{ device_name, unit });
    }

    /// A controller taken back by its driver: closed, and gone from the list, before the call returns.
    pub fn RemBTController(self: *BluetoothBase, device_name: [*:0]const u8, unit: u32) void {
        return libraries.call(self, LVO.RemBTController, Fn.RemBTController, .{ device_name, unit });
    }

    /// The controllers as they are now: a list of BTController, the caller's until ReleaseBTControllers; null for no memory.
    pub fn ObtainBTControllers(self: *BluetoothBase) ?*exec.List {
        return libraries.call(self, LVO.ObtainBTControllers, Fn.ObtainBTControllers, .{});
    }

    /// A list from ObtainBTControllers given back. Null does nothing.
    pub fn ReleaseBTControllers(self: *BluetoothBase, list: ?*exec.List) void {
        return libraries.call(self, LVO.ReleaseBTControllers, Fn.ReleaseBTControllers, .{list});
    }

    /// A task signalled whenever the controllers change; null for no memory.
    pub fn AddBTNotify(self: *BluetoothBase, task: *exec.Task, signals: u32) ?*bluetooth.BTNotify {
        return libraries.call(self, LVO.AddBTNotify, Fn.AddBTNotify, .{ task, signals });
    }

    /// A notification given back: its task is told no more. Null does nothing.
    pub fn RemBTNotify(self: *BluetoothBase, notify: ?*bluetooth.BTNotify) void {
        return libraries.call(self, LVO.RemBTNotify, Fn.RemBTNotify, .{notify});
    }
};
